222	/**
223	 * Returns arguments for the Linux 'find' command to locate secret files.
224	 */
225	export function getSecretFileFindArgs(): string[] {
226	  const args: string[] = ['('];
227	  SECRET_FILES.forEach((s, i) => {
228	    if (i > 0) args.push('-o');
229	    args.push('-name', s.pattern);
230	  });
231	  args.push(')');
232	  return args;
233	}
